+fn top_face_id(c: &mut Client, model_name: &str, z: f64) -> String {
+    let feats = c.ok("list_features", json!({ "model": model_name, "kinds": ["faces"] }));
+    feats["faces"]
+        .as_array()
+        .expect("faces")
+        .iter()
+        .find(|f| f["bounds"]["min"][2].as_f64().is_some_and(|fz| (fz - z).abs() < 1e-3))
+        .expect("top face")["id"]
+        .as_str()
+        .expect("face id")
+        .to_owned()
+}
