+
+impl KoIndex {
+    fn of(ko: &Region) -> Self {
+        let mut segs = Vec::new();
+        for l in ko.loops() {
+            let pts = l.points();
+            let n = pts.len();
+            for i in 0..n {
+                segs.push((pts[i], pts[(i + 1) % n]));
+            }
+        }
+        Self { bounds: ko.bounds(), segs }
+    }
+}
