+
+fn push_seg(runs: &mut Vec<Vec<Point2>>, a: Point2, b: Point2) {
+    if dist(a, b) <= EPS_LEN {
+        return;
+    }
+    if let Some(last) = runs.last_mut()
+        && let Some(&end) = last.last()
+        && dist(end, a) <= EPS_LEN
+    {
+        if dist(end, b) > EPS_LEN {
+            last.push(b);
+        }
+        return;
+    }
+    runs.push(vec![a, b]);
+}
