+fn trim_open_run(run: &[Point2], ko_clr: &Region, clr_idx: &KoIndex) -> Vec<Vec<Point2>> {
+    if run.len() < 2 {
+        return Vec::new();
+    }
+    let mut out = Vec::new();
+    for w in run.windows(2) {
+        for (p, q) in clip_outside(ko_clr, clr_idx, w[0], w[1]) {
+            push_seg(&mut out, p, q);
+        }
+    }
+    out
+}
